void oled_write_image_16x16(const char *image, uint8_t cell_x, uint8_t cell_y) {
	// Each image is 16x16 → 2 vertical pages (8 pixels per page)
	for (uint8_t row = 0; row < 2; row++) { // top page and bottom page
		oled_set_cursor(cell_x, cell_y + row); // set page
		oled_write_raw_P(&image[row * 16], 16); // write 16 bytes for this row
	}
}

void oled_write_digit_16x16(uint8_t digit, uint8_t cell_x, uint8_t cell_y) {
	if (digit > 9) return;

	// Each digit is 16x16 → 2x2 cells
	for (uint8_t row = 0; row < 2; row++) { // 2 vertical cells
		oled_set_cursor(cell_x, cell_y + row); // move to cell
		oled_write_raw_P(&digit_images_16x16[digit][row * 16], 16); // write 16 bytes per row
	}
}

void oled_write_number_16x16(uint32_t number, uint8_t start_cell_x, uint8_t start_cell_y) {
	char buf[11];
	snprintf(buf, sizeof(buf), "%lu", (unsigned long)number);

	uint8_t x = start_cell_x;
	uint8_t y = start_cell_y;
	uint8_t digits_in_row = 0;

	for (uint8_t i = 0; buf[i] != '\0'; i++) {
		uint8_t digit = buf[i] - '0';
		oled_write_digit_16x16(digit, x, y);

		x += 2;               // move 2 cells to the right for next digit
		digits_in_row++;

		if (digits_in_row >= 2) {  // 2 digits per row → wrap
			digits_in_row = 0;
			x = start_cell_x;      // reset x to start
			y += 2;                // move 2 cells down for next row
		}
	}
}